// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        vm.assume(_tos.length > 0);
        vm.assume(caddress != address(0));
        uint balanceBefore = address(c).balance;
        (bool success, bytes memory returnData) = address(c).call(abi.encodeWithSelector(c.transfer.selector, from, caddress, _tos, v));
        assertTrue(success && abi.decode(returnData, (bool)));
    }
}

